import React, { useState, useEffect, useCallback } from 'react'
import { useContexState } from '../hooks/context'

import api from '../services/api'

interface ConvertListParam {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
    }[]
};

interface ConvertListReturn {
    [key: string]: [{
        id: number;
        name: string;
        phone: string;
        price: number;
    }]
}

interface NumbersType {
    lineCards: number;
    id: string;
}

export function useLoadPage() {
    const [getList, setGetList] = useState<ConvertListReturn>();
    const [qwe, asd] = useState(0)

    const {
        loading,
        page,
        total,
        feed
    } = useContexState();

    const {
        setFeed,
        setLoading,
        setPage,
    } = useContexState();

    function convertList({ data }: ConvertListParam) {
        return data.reduce<any>((h, card) =>
            Object.assign(h, {
                [card.number]: (h[card.number] || [])
                    .concat(
                        {
                            id: card.id,
                            name: card.name,
                            phone: card.phone,
                            price: card.price,
                        })
            }), {}
        );
    };


    function jkl(i) {

        api.get("getCards", {
            params: {
                firstNumber: Number(i),
                lastNumber: Number(i) + 200
            }
        }
        ).then((responce) => {
            console.log(JSON.stringify(responce.data));
            setGetList(convertList(responce))
        })

        setFeed(i)
    }


    function LoadPage(value: string | number = 0) {
        if (page === total) return;
        if (loading) return;

        setLoading(true);

        const perPage = 84;
        const numbers: NumbersType[] = []

        for (let i = 0; i < perPage; i++) {
            numbers.push({ lineCards: (i * 6) + Number(value), id: String(i) })
        }




        setLoading(false);
        setPage(page + 1);
        setFeed([...numbers])
        jkl(i[0]?.lineCards);
    }

    return { LoadPage, getList }
}
